-- 原宣战报名独立事实；不生成比赛结果或奖励。
CREATE TABLE IF NOT EXISTS p13_union_fight_entries (guild_id VARCHAR(64) NOT NULL,day VARCHAR(10) NOT NULL,applied_at BIGINT NOT NULL,deadline BIGINT NOT NULL,frozen_at BIGINT NOT NULL DEFAULT 0,eligible_count INT NOT NULL DEFAULT 0,adjust_times_used INT NOT NULL DEFAULT 0,match_processed BOOLEAN NOT NULL DEFAULT FALSE,frozen_tables LONGBLOB,configuration_hash CHAR(64) NOT NULL DEFAULT '',engine_version VARCHAR(128) NOT NULL DEFAULT '',client_version VARCHAR(128) NOT NULL DEFAULT '',source TEXT NOT NULL,PRIMARY KEY(guild_id,day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
